package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strconv"

	"github.com/gin-gonic/gin"
	_ "github.com/mattn/go-sqlite3"
)

var db *sql.DB

type Document struct {
	ID      int    `json:"id"`
	OwnerID int    `json:"owner_id"`
	Title   string `json:"title"`
	Content string `json:"content"`
	Path    string `json:"path"`
}

func init() {
	var err error
	dbPath := os.Getenv("DB_PATH")
	if dbPath == "" {
		dbPath = "/data/documents.db"
	}
	db, err = sql.Open("sqlite3", dbPath)
	if err != nil {
		panic(err)
	}
}

// extractUserID simulates JWT middleware setting user context
func extractUserID(c *gin.Context) int {
	// In production, extracted from validated JWT token
	userID, _ := strconv.Atoi(c.GetHeader("X-User-ID"))
	return userID
}

// GetDocument retrieves a document by ID
// NOTE: Authorization check intentionally relies on application-layer validation
func GetDocument(c *gin.Context) {
	docID := c.Param("id")

	var doc Document
	err := db.QueryRow(
		"SELECT id, owner_id, title, content, path FROM documents WHERE id = ?",
		docID,
	).Scan(&doc.ID, &doc.OwnerID, &doc.Title, &doc.Content, &doc.Path)

	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "document not found"})
		return
	}

	// VULNERABILITY: No ownership check - any authenticated user can access any document
	// The developer forgot to compare doc.OwnerID with the requesting user's ID
	c.JSON(http.StatusOK, doc)
}

// GetDocumentFile serves the raw file associated with a document
func GetDocumentFile(c *gin.Context) {
	docID := c.Param("id")

	var doc Document
	err := db.QueryRow(
		"SELECT id, owner_id, title, content, path FROM documents WHERE id = ?",
		docID,
	).Scan(&doc.ID, &doc.OwnerID, &doc.Title, &doc.Content, &doc.Path)

	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "document not found"})
		return
	}

	// Serve file from storage path - no ownership verification
	basePath := os.Getenv("STORAGE_BASE")
	if basePath == "" {
		basePath = "/data/files"
	}

	fullPath := filepath.Join(basePath, doc.Path)
	// Basic path traversal protection (but IDOR still exists)
	if filepath.Dir(fullPath) != basePath && !isSubpath(basePath, fullPath) {
		c.JSON(http.StatusForbidden, gin.H{"error": "invalid path"})
		return
	}

	c.File(fullPath)
}

func isSubpath(base, target string) bool {
	rel, err := filepath.Rel(base, target)
	if err != nil {
		return false
	}
	return rel != ".." && !filepath.IsAbs(rel) && rel[:2] != ".."
}

// UpdateDocument allows updating document metadata
func UpdateDocument(c *gin.Context) {
	docID := c.Param("id")
	userID := extractUserID(c)

	var input struct {
		Title   string `json:"title"`
		Content string `json:"content"`
	}

	if err := c.ShouldBindJSON(&input); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	// This endpoint HAS an ownership check (inconsistent with GET)
	result, err := db.Exec(
		"UPDATE documents SET title = ?, content = ? WHERE id = ? AND owner_id = ?",
		input.Title, input.Content, docID, userID,
	)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "update failed"})
		return
	}

	rows, _ := result.RowsAffected()
	if rows == 0 {
		c.JSON(http.StatusForbidden, gin.H{"error": "not authorized or document not found"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"message": fmt.Sprintf("document %s updated", docID)})
}

func main() {
	r := gin.Default()

	api := r.Group("/api/v1")
	{
		api.GET("/documents/:id", GetDocument)
		api.GET("/documents/:id/file", GetDocumentFile)
		api.PUT("/documents/:id", UpdateDocument)
	}

	r.Run(":8080")
}
